#!/usr/bin/env node
// scaffold-charts-library.js — v78 ship 3 thin Recharts wrappers
// (BarChart / LineChart / PieChart) so the LLM doesn't reinvent
// SVG positioning per dashboard.
//
// Adds recharts to deps.
// Idempotent. Marker: '// Generated by scaffold-charts-library'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--force') out.force = true;
    else if (a === '--dry-run') out.dryRun = true;
  }
  if (!out.target) { console.error('Usage: scaffold-charts-library --target FRONTEND_DIR'); process.exit(1); }
  return out;
}

function marker() { return '// Generated by scaffold-charts-library — DO NOT EDIT BY HAND. Re-run to refresh.'; }

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-charts-library/.test(existing) && !force) return { written: false, reason: 'exists-handauthored' };
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

function ensureDep(pkgPath, deps, dryRun) {
  if (!fs.existsSync(pkgPath)) return { changed: false, reason: 'no-package-json' };
  var pkg; try { pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8')); } catch (_) { return { changed: false, reason: 'parse-error' }; }
  pkg.dependencies = pkg.dependencies || {};
  var added = [];
  Object.keys(deps).forEach(function (k) {
    if (!pkg.dependencies[k] && !(pkg.devDependencies || {})[k]) { pkg.dependencies[k] = deps[k]; added.push(k); }
  });
  if (!added.length) return { changed: false, reason: 'already-present' };
  if (dryRun) return { changed: false, reason: 'dry-run', added: added };
  fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
  return { changed: true, added: added };
}

var BAR = [
  marker(),
  "import { Bar, BarChart as ReBarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';",
  '',
  'export interface BarChartProps {',
  '  data: Array<Record<string, number | string>>;',
  '  xKey: string;',
  '  yKey: string;',
  '  height?: number;',
  '  testId?: string;',
  '}',
  '',
  "export function BarChart({ data, xKey, yKey, height = 240, testId = 'bar-chart' }: BarChartProps) {",
  '  return (',
  '    <div data-testid={testId} style={{ width: \'100%\', height }}>',
  '      <ResponsiveContainer>',
  '        <ReBarChart data={data}>',
  '          <CartesianGrid strokeDasharray="3 3" />',
  '          <XAxis dataKey={xKey} />',
  '          <YAxis />',
  '          <Tooltip />',
  '          <Bar dataKey={yKey} fill="currentColor" className="text-primary" />',
  '        </ReBarChart>',
  '      </ResponsiveContainer>',
  '    </div>',
  '  );',
  '}',
  '',
].join('\n');

var LINE = [
  marker(),
  "import { CartesianGrid, Line, LineChart as ReLineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';",
  '',
  'export interface LineChartProps {',
  '  data: Array<Record<string, number | string>>;',
  '  xKey: string;',
  '  yKey: string;',
  '  height?: number;',
  '  testId?: string;',
  '}',
  '',
  "export function LineChart({ data, xKey, yKey, height = 240, testId = 'line-chart' }: LineChartProps) {",
  '  return (',
  '    <div data-testid={testId} style={{ width: \'100%\', height }}>',
  '      <ResponsiveContainer>',
  '        <ReLineChart data={data}>',
  '          <CartesianGrid strokeDasharray="3 3" />',
  '          <XAxis dataKey={xKey} />',
  '          <YAxis />',
  '          <Tooltip />',
  '          <Line type="monotone" dataKey={yKey} stroke="currentColor" className="text-primary" dot={false} />',
  '        </ReLineChart>',
  '      </ResponsiveContainer>',
  '    </div>',
  '  );',
  '}',
  '',
].join('\n');

var PIE = [
  marker(),
  "import { Cell, Pie, PieChart as RePieChart, ResponsiveContainer, Tooltip } from 'recharts';",
  '',
  'export interface PieDatum { name: string; value: number; fill?: string; }',
  '',
  'export interface PieChartProps {',
  '  data: PieDatum[];',
  '  height?: number;',
  '  testId?: string;',
  '}',
  '',
  "const PALETTE = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#06b6d4', '#84cc16', '#ec4899'];",
  '',
  "export function PieChart({ data, height = 240, testId = 'pie-chart' }: PieChartProps) {",
  '  return (',
  '    <div data-testid={testId} style={{ width: \'100%\', height }}>',
  '      <ResponsiveContainer>',
  '        <RePieChart>',
  '          <Pie data={data} dataKey="value" nameKey="name" innerRadius={40} outerRadius={80}>',
  '            {data.map((d, i) => (',
  '              <Cell key={d.name} fill={d.fill ?? PALETTE[i % PALETTE.length]} />',
  '            ))}',
  '          </Pie>',
  '          <Tooltip />',
  '        </RePieChart>',
  '      </ResponsiveContainer>',
  '    </div>',
  '  );',
  '}',
  '',
].join('\n');

function main() {
  var args = parseArgs(process.argv);
  var files = [
    { p: 'app/components/charts/BarChart.tsx', c: BAR },
    { p: 'app/components/charts/LineChart.tsx', c: LINE },
    { p: 'app/components/charts/PieChart.tsx', c: PIE },
  ];
  var written = 0, skipped = 0;
  files.forEach(function (f) {
    var r = writeIfManaged(path.join(args.target, f.p), f.c, args.force, args.dryRun);
    if (r.written) written++; else skipped++;
  });
  var d = ensureDep(path.join(args.target, 'package.json'), { 'recharts': '^2.12.0' }, args.dryRun);
  console.log('scaffold-charts-library: ' + written + ' written, ' + skipped + ' skipped, deps=' + (d.changed ? '+' + d.added.join(',') : d.reason));
}

main();
